SELECT (CASE WHEN ("CommonGovernment_13"."refidvid_piid" IS NULL) THEN null WHEN ("CommonGovernment_13"."refidvid_piid" = ' ') THEN null ELSE "CommonGovernment_13"."refidvid_piid" END) AS "Refidvid_Piid__group_",   "CommonGovernment_13"."award_type" AS "award_type",   SUM("CommonGovernment_13"."obligatedamount") AS "sum_obligatedamount_ok" FROM "CommonGovernment_13" GROUP BY "Refidvid_Piid__group_",   "CommonGovernment_13"."award_type";
